input.command:
$dest = "\\192.168.31.188\Incoming\LAPTOP\arte\20261112_guia-visual"
$ws = "C:\Users\Romelt\Documents\PixeloramaAIWorkspace"
$desk = "C:\Users\Romelt\Desktop"
$prevSrc = "$env:TEMP\pxo_previews"

Copy-Item -LiteralPath "$ws\guia_linea_visual.md" -Destination $dest -Force
Copy-Item -LiteralPath "$ws\informe_estilo_bits.md" -Destination $dest -Force

$pxos = @('baston1.pxo','baston1.2.pxo','baston2.pxo','baston3.pxo','axe.pxo','valki.pxo','spada.pxo','sscudo.pxo','sscudo adnto.pxo')
foreach ($f in $pxos) {
  $src = Join-Path $desk $f
  if (-not (Test-Path -LiteralPath $src)) { Write-Error "Missing: $src"; continue }
  Copy-Item -LiteralPath $src -Destination $dest -Force
}

if (Test-Path $prevSrc) {
  Get-ChildItem -LiteralPath $prevSrc -Filter *.png | ForEach-Object {
    Copy-Item -LiteralPath $_.FullName -Destination "$dest\previews\" -Force
  }
}

Write-Host "=== PXO META ==="
$pxos | ForEach-Object {
  $p = Join-Path $desk $_
  Get-Item -LiteralPath $p | Select-Object Name, Length, CreationTime, LastWriteTime
}

Write-Host "=== COPIED LIST ==="
Get-ChildItem -LiteralPath $dest -Recurse | Select-Object FullName, Length, CreationTime, LastWriteTime | Sort-Object FullName
